config.prompt:
Hacker News post:
TITLE: {{input.title}}
SUMMARY: {{input.summary ?? "(none provided — base your sentence on the title alone)"}}

Write exactly one sentence explaining why this post matters (novelty, practical use, scale, or controversy), grounded strictly in the title and summary above.

config.code:
const rel = nodes.classify_ai_ml.output.relevance;
const conf = nodes.classify_ai_ml.output.answers.relevance.confidence;
return {
  is_ai_ml: rel === "relevant",
  status: rel,
  why_it_matters: nodes.write_why_it_matters.output.text ?? "",
  reason: rel === "relevant"
    ? "AI/ML is the core subject (confidence " + conf + ")"
    : "Not primarily about AI/ML (confidence " + conf + ")"
};

